# ai_orchestrator/app/core/pagination.py

from sqlalchemy.orm import Query
from sqlalchemy import func
from math import ceil
from typing import List, Any, Optional

class PaginationMeta:
    def __init__(self, total_count: int, current_page: int, page_size: int, total_pages: int):
        self.total_count = total_count
        self.current_page = current_page
        self.page_size = page_size
        self.total_pages = total_pages

class PaginatedResult:
    def __init__(self, items: List[Any], total: int, page: int, per_page: int):
        self.items = items
        self.total = total
        self.page = page
        self.per_page = per_page
        self.pages = ceil(total / per_page)

def paginate_query(
    db: Any, query: Query, page: int, limit: int
) -> PaginatedResult:
    total = query.with_entities(func.count()).scalar()
    items = query.offset((page - 1) * limit).limit(limit).all()
    return PaginatedResult(items, total, page, limit)
