from fastapi.testclient import TestClient
from ai_orchestrator.app.main import app
from ai_orchestrator.app.db.session import get_db
from ai_orchestrator.app.models.time_log import TimeLog
from ai_orchestrator.app.db.base_class import Base
from sqlalchemy import create_engine
from sqlalchemy.orm import sessionmaker
from ai_orchestrator.app.core.config import settings
from ai_orchestrator.app.schemas.time_log import TimeLogCreate
import pytest

client = TestClient(app)

# Configure test database
SQLALCHEMY_DATABASE_URL = f"postgresql://{settings.TEST_DB_USER}:{settings.TEST_DB_PASSWORD}@{settings.TEST_DB_HOST}/{settings.TEST_DB_NAME}"
engine = create_engine(SQLALCHEMY_DATABASE_URL)
TestingSessionLocal = sessionmaker(autocommit=False, autoflush=False, bind=engine)

Base.metadata.create_all(bind=engine)

def override_get_db():
    try:
        db = TestingSessionLocal()
        yield db
    finally:
        db.close()

app.dependency_overrides[get_db] = override_get_db

def test_get_time_logs_pagination():
    db = TestingSessionLocal()
    for i in range(1, 6):
        log = TimeLog(
            start_time=f"2023-01-01T00:00:0{i}",
            end_time=f"2023-01-01T00:00:0{i+1}",
            duration=i,
            task_id=i,
            user_id=1,
            status="completed"
        )
        db.add(log)
    db.commit()

    response = client.get("/admin/time_logs", params={"page": 1, "limit": 3})
    assert response.status_code == 200
    data = response.json()
    assert len(data["data"]) == 3
    assert data["meta"]["total_count"] == 5
    assert data["meta"]["current_page"] == 1
    assert data["meta"]["page_size"] == 3
    assert data["meta"]["total_pages"] == 2

    response = client.get("/admin/time_logs", params={"page": 2, "limit": 3})
    assert response.status_code == 200
    data = response.json()
    assert len(data["data"]) == 2
    assert data["meta"]["current_page"] == 2

def test_get_time_logs_invalid_page():
    response = client.get("/admin/time_logs", params={"page": 0, "limit": 50})
    assert response.status_code == 422

def test_get_time_logs_invalid_limit():
    response = client.get("/admin/time_logs", params={"page": 1, "limit": 0})
    assert response.status_code == 422

    response = client.get("/admin/time_logs", params={"page": 1, "limit": 1001})
    assert response.status_code == 422

def test_get_time_logs_no_logs():
    db = TestingSessionLocal()
    db.query(TimeLog).delete()
    db.commit()

    response = client.get("/admin/time_logs", params={"page": 1, "limit": 50})
    assert response.status_code == 200
    data = response.json()
    assert len(data["data"]) == 0
    assert data["meta"]["total_count"] == 0
